from __future__ import absolute_import
from taf.selenium.sbts_fsm3 import pages
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.modals import (RdDebugParametersApplyChangesModal,
                                            RestoreToAllRdDebugParametersModal,
                                            PowerResetModal)


class Procedures(pages.Procedures):
    def __init__(self, driver):
        super(Procedures, self).__init__(driver)
        self._bts_rd_debug_parameters_management = BtsRdDebugParametersManagementPage(driver)
        self._bts_non_default_rd_debug_parameters_management = BtsNonDefaultRdDebugParametersManagementPage(driver)
        self._bts_power_reset = BtsPowerRestPage(driver)

    @property
    def bts_rd_debug_parameters_management(self):
        return self._bts_rd_debug_parameters_management

    @property
    def bts_non_default_rd_debug_parameters_management(self):
        return self._bts_non_default_rd_debug_parameters_management

    @property
    def bts_power_reset(self):
        return self._bts_power_reset


class BtsRdDebugParametersManagementPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Procedures', 'BTS R&D Debug Parameters Management', 'R&D Debug Parameters']

    def __init__(self, driver):
        super(BtsRdDebugParametersManagementPage, self).__init__(driver)
        self._view_panel = BtsRdDebugParametersManagementViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def change_rd_debug_parameters(self, domain, parameter_name, current_value=None, persistency=None, timeout=60):
        self._view_panel.change_rd_debug_parameters(domain, parameter_name, current_value, persistency, timeout)

    def apply_rd_debug_parameters_changes(self, timeout=60):
        return self._view_panel.apply_rd_debug_parameters_changes(timeout)


class BtsRdDebugParametersManagementViewPanel(ViewPanel):
    _RAD_DEBUG_DOMAIN = '//*[@class="rad-debug-domains"]//li[span[text()="{}"]]'
    _PARAMETER = '//*[@class="bts-rd-debug-parameter-table"]//th[text()="Parameter name"]'
    _RELOAD_PARAMETERS = '//*[@class="rad-debug-parameters"]//span[text()="Reload Parameters"]'
    _PARAMETER_TR = ('//tr[td//span[translate(text(), "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")='
                     '"{}"]]')
    _CURRENT_VALUE_DROPDOWN_SPAN = _PARAMETER_TR + '//td[@class="current-value-col"]//span[@id]'
    _CURRENT_VALUE_INPUT = _PARAMETER_TR + '//td[@class="current-value-col"]//input'
    _CURRENT_VALUE_OPTIONS = '//ul[contains(@id, "{}")]//span'
    _PERSISTENCY_DROPDOWN_BUTTON = '//*[@class="apply-changes"]//p-dropdown'
    _PERSISTENCY_VALUE_OPTIONS = '//p-dropdownitem//li'
    _APPLY_CHANGES = '//button[span[text()="Apply Changes"]]'
    _APPLY_CHANGES_ONGOING = '//ot-instruction//*[contains(text(), "Apply changes ongoing")]'
    _APPLY_CHANGES_SUCCESS = '//ot-instruction//*[contains(text(), "Apply changes success")]'
    _STATUS = '//ot-instruction'

    def __init__(self, driver):
        super(BtsRdDebugParametersManagementViewPanel, self).__init__(driver)

    def change_rd_debug_parameters(self, domain, parameter_name, current_value=None, persistency=None, timeout=60):
        self.click_enabled_element((By.XPATH, self._RAD_DEBUG_DOMAIN.format(domain)), timeout)
        self.wait_for_enable((By.XPATH, self._PARAMETER), timeout)

        if current_value is not None:
            try:
                current_value_dropdown_button = self._CURRENT_VALUE_DROPDOWN_SPAN.format(parameter_name.lower())
                self.wait_for_enable((By.XPATH, current_value_dropdown_button), 5)
                id_value = self.get_attribute((By.XPATH, current_value_dropdown_button), "id").rsplit('_', 1)[
                    0]
                self.select_element_from_dropdown_list_by_text_and_click(
                    current_value,
                    (By.XPATH, current_value_dropdown_button),
                    (By.XPATH, self._CURRENT_VALUE_OPTIONS.format(id_value)),
                    timeout
                )
            except TimeoutException:
                self.insert_text_to_enable_element((By.XPATH, self._CURRENT_VALUE_INPUT.format(parameter_name.lower())),
                                                   current_value)

        if persistency:
            self.select_element_from_dropdown_list_by_text_and_click(
                persistency,
                (By.XPATH, self._PERSISTENCY_DROPDOWN_BUTTON),
                (By.XPATH, self._PERSISTENCY_VALUE_OPTIONS),
                timeout
            )

    def apply_rd_debug_parameters_changes(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._APPLY_CHANGES), timeout)
        modal = RdDebugParametersApplyChangesModal(self.driver)
        if modal.wait_until_apply_changes_modal_appear():
            modal.apply()
            self.wait_for_visibility_by_xpath(self._APPLY_CHANGES_ONGOING)
            try:
                self.wait_for_invisibility((By.XPATH, self._APPLY_CHANGES_ONGOING))
                self.wait_for_visibility_by_xpath(self._APPLY_CHANGES_SUCCESS, timeout)
                self.wait_for_invisibility((By.XPATH, self._APPLY_CHANGES_SUCCESS))
            except TimeoutException:
                pass
            return self.get_text_by_xpath(self._STATUS)


class BtsNonDefaultRdDebugParametersManagementPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Procedures', 'BTS R&D Debug Parameters Management', 'Non-Default R&D Debug Parameters']

    def __init__(self, driver):
        super(BtsNonDefaultRdDebugParametersManagementPage, self).__init__(driver)
        self._view_panel = BtsNonDefaultRdDebugParametersManagementViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def restore_all_rd_debug_parameters_to_defaults(self, timeout=60):
        return self._view_panel.restore_all_rd_debug_parameters_to_defaults(timeout)


class BtsNonDefaultRdDebugParametersManagementViewPanel(ViewPanel):
    _RESTORE_TO_ALL_BUTTON = '//div[@class="non-default-rd-parameters"]//button[*[text()="Restore All to Defaults"]]'
    _RESTORE_SUCCESS = ('//ot-instruction//span[contains(text(), '
                        '"Restore success, fetch non-default R&D debug parameters success")]')
    _STATUS = '//ot-instruction'

    def __init__(self, driver):
        super(BtsNonDefaultRdDebugParametersManagementViewPanel, self).__init__(driver)

    def restore_all_rd_debug_parameters_to_defaults(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._RESTORE_TO_ALL_BUTTON), timeout)
        restore_modal = RestoreToAllRdDebugParametersModal(self.driver)
        restore_modal.wait_until_apply_changes_modal_appear()
        restore_modal.restore()
        self.wait_for_visibility_by_xpath(self._RESTORE_SUCCESS)
        return self.get_text_by_xpath(self._STATUS)


class BtsPowerRestPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Procedures', 'BTS Power Reset']

    def __init__(self, driver):
        super(BtsPowerRestPage, self).__init__(driver)
        self._view_panel = BtsPowerRestPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def power_reset(self, timeout=60):
        return self._view_panel.power_reset(timeout)


class BtsPowerRestPageViewPanel(ViewPanel):
    POWER_RESET = '//*[text()="Power reset"]'
    STARTING_POWER_RESET = 'Starting power reset'
    POWER_RESET_STATUS = '//span[contains(text(), "{}")]'.format(STARTING_POWER_RESET)
    EXECUTE = '//div[@class="power-reset-actions"]//span[text()="Execute"]'
    RESET_STATUS = '//ot-instruction//span'

    def __init__(self, driver):
        super(BtsPowerRestPageViewPanel, self).__init__(driver)

    def power_reset(self, timeout=60):
        self.click_enabled_element((By.XPATH, self.EXECUTE), timeout)
        power_reset = PowerResetModal(self.driver)
        power_reset.wait_until_power_reset_modal_appear(timeout)
        power_reset.execute(timeout=timeout)
        self.wait_for_visibility_by_xpath(self.POWER_RESET_STATUS, timeout)
        self.wait_for_invisibility(self.POWER_RESET_STATUS, timeout)
        try:
            return self.get_text_by_xpath(self.RESET_STATUS, 5)
        except TimeoutException:
            return self.STARTING_POWER_RESET
